"""Build a read-only source gallery from real Blender renders and contracts."""
import json, html
from pathlib import Path
KIT=Path(__file__).resolve().parents[2]/'kit'
data=json.loads((KIT/'contracts.json').read_text(encoding='utf-8'))
cards=[]
for item in data['assets']:
    size=' × '.join(f'{v:g}' for v in item['logicalSizeMeters'])+' m'
    cards.append(f'''<article><a href="{html.escape(item['preview'])}"><img src="{html.escape(item['preview'])}" alt="{html.escape(item['title'])}的实际 Blender 渲染"></a><div class="copy"><span class="number">{item['number']:02d}</span><h2>{html.escape(item['title'])}</h2><p>{size}</p><p class="role">{html.escape(item['role'])}</p><footer><a href="{html.escape(item['source'])}">原生源</a><a href="{html.escape(item['fbx'])}">实际 FBX</a><a href="{html.escape(item['palette'])}">色板</a></footer></div></article>''')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SB-03 原创桥梁素材</title><style>*{box-sizing:border-box}body{margin:0;background:#142026;color:#e1e5de;font:16px/1.6 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1180px;margin:auto;padding:44px 24px 64px}.tag{color:#99b9bd;letter-spacing:3px;font-size:12px}h1{font-size:34px;font-weight:600;margin:8px 0 14px}header p{max-width:840px;color:#b4c4c7}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:32px}article{background:#203139;border:1px solid #33474e}img{display:block;width:100%;aspect-ratio:1;object-fit:contain;background:#252c34}.copy{padding:18px 20px}.number{float:right;font-size:26px;line-height:1;color:#7d9ca3}h2{font-size:20px;margin:0 0 8px;color:#ece2c9}p{margin:0 0 5px}.role{font:12px/1.5 ui-monospace,monospace;color:#9bb3bb}footer{display:flex;gap:18px;border-top:1px solid #3a4d52;padding-top:14px;margin-top:16px;font-size:13px}a{color:#bddbdd;text-decoration:none}a:hover{text-decoration:underline}.notes{margin-top:28px;color:#a9bdc2}@media(max-width:780px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:490px){.grid{grid-template-columns:1fr}}</style><main><header><div class="tag">SB-03 / ORIGINAL WORKSHOP KIT / V1</div><h1>实际用什么素材来造桥</h1><p>这里展示工坊产出的9件原创模型，图片均为实际 Blender 渲染。编号供桥上来源高亮对照：Unity负责安排它们的数量、位置与连接，并为配方允许的桥芯区域生成结构。</p><p>细节单元0.125m，底部中心枢轴。实际FBX直接参与组合；不将整座桥反复盖章，也不把素材当作地形参考场。</p></header><section class="grid">'''+''.join(cards)+'''</section><p class="notes">九件源、FBX、色板均已独立重开验证。<a href="ASSET_REPORT.md">素材契约与验证边界</a> · <a href="contracts.json">完整来源清单</a></p></main></html>'''
(KIT/'index.html').write_text(page,encoding='utf-8')
